using System;
using System.Data;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

namespace InformationWeb.Controls.Graduation
{
    /// <summary>
    /// Mẫu 2 — Giấy xác nhận hoàn thành khóa đào tạo lái xe (A5 ngang). Hạng A1, A0.
    /// </summary>
    public static class GraduationXacNhanHoanThanhPdfFiller
    {
        private const float MARGIN = 32F;
        private const float FONT_BODY = 13F;
        private const float FONT_TITLE = 14F;
        private const float FONT_HEADER = 12F;

        public static void CreatePdf(string outputPath, DataRow drw)
        {
            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);

            Document document = new Document(PageSize.A5.Rotate(), MARGIN, MARGIN, MARGIN, MARGIN);
            FileStream fs = null;
            PdfWriter writer = null;

            try
            {
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                writer = PdfWriter.GetInstance(document, fs);
                document.Open();

                BaseFont bfRegular = CreateUnicodeFont(false);
                BaseFont bfBold = CreateUnicodeFont(true);
                Font fontBody = new Font(bfRegular, FONT_BODY);
                Font fontBodyBold = new Font(bfBold, FONT_BODY);
                Font fontTitle = new Font(bfBold, FONT_TITLE);
                Font fontHeader = new Font(bfBold, FONT_HEADER);

                DrawDoubleBorder(writer, document);

                AddCentered(document, "CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM", fontHeader, 0, 6);
                Paragraph paraMotto = new Paragraph("Độc lập - Tự do - Hạnh phúc", fontHeader);
                paraMotto.Alignment = Element.ALIGN_CENTER;
                paraMotto.SpacingAfter = 2;
                document.Add(paraMotto);
                LineSeparator lineMotto = new LineSeparator(0.5F, 42F, BaseColor.BLACK, Element.ALIGN_CENTER, -2);
                document.Add(new Chunk(lineMotto));

                document.Add(Spacer(10));
                AddCentered(document, "GIẤY XÁC NHẬN HOÀN THÀNH KHÓA ĐÀO TẠO LÁI XE", fontTitle, 0, 8);

                string strCerNo = GetString(drw, "CerNo");
                Paragraph paraSo = new Paragraph(String.Format("Số: {0}", strCerNo), fontBody);
                paraSo.Alignment = Element.ALIGN_CENTER;
                paraSo.SpacingAfter = 14;
                document.Add(paraSo);

                document.Add(BodyLine("Trường Cao đẳng nghề số 21 xác nhận:", fontBodyBold, 0, 10));
                document.Add(BodyLine(String.Format("Ông (bà): {0}", GetString(drw, "StudentFullName")), fontBody, 0, 6));
                document.Add(BodyLine(String.Format("Ngày tháng năm sinh: {0}    số CCCD/CC: {1}",
                    GetString(drw, "BirthDateText"),
                    GetString(drw, "PersonID")), fontBody, 0, 8));

                string strHang = GetString(drw, "SpecialBranchID");
                document.Add(MixedBodyLine(
                    "Đã hoàn thành chương trình đào tạo lái xe hạng: ",
                    strHang,
                    fontBody,
                    fontBodyBold,
                    8));

                string strDayOfCourse = GetString(drw, "DayOfCourse");
                string strStartAt = FormatDateValue(drw, "StartAt");
                string strFinishAt = FormatDateValue(drw, "FinishAt");
                document.Add(BodyLine(String.Format("Thời gian học: {0} ngày, từ ngày {1} đến ngày {2}",
                    strDayOfCourse, strStartAt, strFinishAt), fontBody, 0, 8));

                document.Add(MixedBodyLine(
                    "Tại: ",
                    "Trung tâm Đào tạo & SHLX số 3 - Trường Cao đẳng nghề số 21.",
                    fontBody,
                    fontBodyBold,
                    16));

                DateTime dtmSigning = GetSigningDate(drw);
                Paragraph paraSignDate = new Paragraph(String.Format("TP. Hồ Chí Minh, ngày {0} tháng {1} năm {2}",
                    dtmSigning.Day, dtmSigning.Month, dtmSigning.Year), fontBody);
                paraSignDate.Alignment = Element.ALIGN_RIGHT;
                paraSignDate.SpacingAfter = 4;
                document.Add(paraSignDate);

                AddCentered(document, "KT. HIỆU TRƯỞNG", fontBodyBold, Element.ALIGN_RIGHT, 0);
                Paragraph paraPho = new Paragraph("PHÓ HIỆU TRƯỞNG", fontBodyBold);
                paraPho.Alignment = Element.ALIGN_RIGHT;
                paraPho.SpacingAfter = 48;
                document.Add(paraPho);

                Paragraph paraName = new Paragraph("Đại tá Vũ Thanh Thế", fontBodyBold);
                paraName.Alignment = Element.ALIGN_RIGHT;
                document.Add(paraName);
            }
            finally
            {
                if (document != null && document.IsOpen())
                    document.Close();
                if (writer != null)
                    writer.Close();
                if (fs != null)
                    fs.Dispose();
            }
        }

        private static void DrawDoubleBorder(PdfWriter writer, Document document)
        {
            PdfContentByte canvas = writer.DirectContent;
            float w = document.PageSize.Width;
            float h = document.PageSize.Height;
            float inset = 14F;
            float gap = 3F;

            canvas.SetLineWidth(0.8F);
            canvas.Rectangle(inset, inset, w - inset * 2F, h - inset * 2F);
            canvas.Stroke();
            canvas.Rectangle(inset + gap, inset + gap, w - (inset + gap) * 2F, h - (inset + gap) * 2F);
            canvas.Stroke();
        }

        private static Paragraph BodyLine(string text, Font font, float spacingBefore, float spacingAfter)
        {
            Paragraph p = new Paragraph(text, font);
            p.Alignment = Element.ALIGN_LEFT;
            p.SpacingBefore = spacingBefore;
            p.SpacingAfter = spacingAfter;
            return p;
        }

        private static Paragraph MixedBodyLine(string prefix, string boldPart, Font fontRegular, Font fontBold, float spacingAfter)
        {
            Phrase phrase = new Phrase();
            phrase.Add(new Chunk(prefix, fontRegular));
            phrase.Add(new Chunk(boldPart, fontBold));
            Paragraph p = new Paragraph(phrase);
            p.Alignment = Element.ALIGN_LEFT;
            p.SpacingAfter = spacingAfter;
            return p;
        }

        private static void AddCentered(Document document, string text, Font font, float spacingBefore, float spacingAfter)
        {
            Paragraph p = new Paragraph(text, font);
            p.Alignment = Element.ALIGN_CENTER;
            p.SpacingBefore = spacingBefore;
            p.SpacingAfter = spacingAfter;
            document.Add(p);
        }

        private static Paragraph Spacer(float height)
        {
            Paragraph p = new Paragraph(" ");
            p.SpacingAfter = height;
            return p;
        }

        private static string GetString(DataRow drw, string columnName)
        {
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            return drw[columnName].ToString().Trim();
        }

        private static string FormatDateValue(DataRow drw, string columnName)
        {
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            DateTime dtm;
            if (DateTime.TryParse(drw[columnName].ToString(), out dtm))
                return dtm.ToString("dd/MM/yyyy");
            return drw[columnName].ToString().Trim();
        }

        private static DateTime GetSigningDate(DataRow drw)
        {
            if (drw["Signingdate"] != null && drw["Signingdate"] != DBNull.Value)
            {
                DateTime dtm;
                if (DateTime.TryParse(drw["Signingdate"].ToString(), out dtm))
                    return dtm;
            }
            if (drw["CerIssued"] != null && drw["CerIssued"] != DBNull.Value)
            {
                DateTime dtm;
                if (DateTime.TryParse(drw["CerIssued"].ToString(), out dtm))
                    return dtm;
            }
            return DateTime.Now;
        }

        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontFile = bold ? "timesbd.ttf" : "times.ttf";
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);

            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }
    }
}

